function topoOrder(n, edges) {
  const adj = Array.from({ length: n }, () => []), indeg = Array(n).fill(0) //@init
  for (const [a, b] of edges) { adj[a].push(b); indeg[b]++ } //@build
  const queue = [], order = []
  for (let v = 0; v < n; v++) if (indeg[v] === 0) queue.push(v) //@seed
  let head = 0
  while (head < queue.length) {
    const v = queue[head++]; order.push(v) //@pop
    for (const w of adj[v]) {
      indeg[w]-- //@drop
      if (indeg[w] === 0) queue.push(w) //@ready
    }
  }
  return order.length === n ? order : [] //@done
}

