    adj[a].push(b)
    indeg[b]++
  }
  const queue = []
  for (let v = 0; v < n; v++) if (indeg[v] === 0) queue.push(v)
  for (let head = 0; head < queue.length; head++) {
    for (const w of adj[queue[head]]) {
      indeg[w]--
      if (indeg[w] === 0) queue.push(w)
    }
  }
  return queue.length === n ? queue : [] // short means a cycle
}

